# Verification: refetch remaining read threads in inbox/outbox and ensure none violate the exception condition.

def fetch_all_read_threads(category):
    all_items=[]
    page_index=0
    while True:
        if category=='inbox':
            resp = apis.gmail.show_inbox_threads(access_token=gmail_token, read=True, page_index=page_index, page_limit=20)
        elif category=='outbox':
            resp = apis.gmail.show_outbox_threads(access_token=gmail_token, read=True, page_index=page_index, page_limit=20)
        else:
            raise ValueError(category)
        if not resp:
            break
        all_items.extend(resp)
        page_index += 1
    return all_items

inbox_read_after = fetch_all_read_threads('inbox')
outbox_read_after = fetch_all_read_threads('outbox')

print('inbox_read_after_total', len(inbox_read_after))
print('outbox_read_after_total', len(outbox_read_after))

violations=[]
# exception: label in priority_label_set AND starred True
for t in inbox_read_after:
    tid=t['email_thread_id']
    if not (t.get('label') in priority_label_set and bool(t.get('starred'))):
        violations.append(('inbox', tid, t.get('label'), t.get('starred'), t.get('subject'), t.get('created_at')))
for t in outbox_read_after:
    tid=t['email_thread_id']
    if not (t.get('label') in priority_label_set and bool(t.get('starred'))):
        violations.append(('outbox', tid, t.get('label'), t.get('starred'), t.get('subject'), t.get('created_at')))

print('violations_count', len(violations))
print('violations_sample', violations[:10])

# Also print counts of remaining that are spared vs not
spared_after=0
not_spared_after=0
for t in inbox_read_after+outbox_read_after:
    if t.get('label') in priority_label_set and bool(t.get('starred')):
        spared_after += 1
    else:
        not_spared_after += 1
print('spared_after', spared_after, 'not_spared_after', not_spared_after)
